# Import of required libraries
import json
import re

import skyramp

from SkyrampUtils import create_recipe, get_headers, update_recipe


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = get_headers()

    recipes_POST_response = create_recipe(
        client, URL_localhost, headers, "Time Fields Recalculation Probe"
    )

    # POST /api/recipes returns the created recipe's slug as a bare JSON string
    recipes = json.loads(recipes_POST_response.response_body)
    # The name actually sent, including the run-unique suffix
    recipe_name = json.loads(recipes_POST_response.request_body)["name"]

    # Request Body
    recipes_recipes_PATCH_request_body = r'''{
        "cookTime": "1 hour",
        "name": "Time Fields Recalculation Probe",
        "performTime": "15 minutes",
        "prepTime": "30 minutes",
        "totalTime": "1 hour 45 minutes"
    }'''

    assert isinstance(recipes, str) and recipes != ""
    assert re.fullmatch(r"[a-z0-9-]+", recipes)
    assert recipes.startswith("time-fields-recalculation-probe")

    recipes_recipes_PATCH_response = update_recipe(
        client,
        URL_localhost,
        headers,
        recipes,
        recipes_recipes_PATCH_request_body,
        recipe_name,
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes
    assert re.fullmatch(
        r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",
        str(skyramp.get_response_value(recipes_recipes_PATCH_response, "id")),
    )
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "name") == recipe_name
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "prepTime") == "30 minutes"
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "cookTime") == "1 hour"
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "performTime") == "15 minutes"
    assert (
        skyramp.get_response_value(recipes_recipes_PATCH_response, "totalTime")
        == "1 hour 45 minutes"
    )
    assert 0 <= skyramp.get_response_value(recipes_recipes_PATCH_response, "timeFieldsCount") <= 4
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "timeFieldsCount") == 4
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "timeFieldsCount") == sum(
        1
        for _time_field in (
            skyramp.get_response_value(recipes_recipes_PATCH_response, "prepTime"),
            skyramp.get_response_value(recipes_recipes_PATCH_response, "cookTime"),
            skyramp.get_response_value(recipes_recipes_PATCH_response, "performTime"),
            skyramp.get_response_value(recipes_recipes_PATCH_response, "totalTime"),
        )
        if _time_field
    )

    # Request Body
    recipes_recipes_PATCH_1_request_body = r'''{
        "cookTime": null,
        "name": "Time Fields Recalculation Probe",
        "performTime": null,
        "prepTime": null,
        "totalTime": null
    }'''

    recipes_recipes_PATCH_1_response = update_recipe(
        client,
        URL_localhost,
        headers,
        skyramp.get_response_value(recipes_recipes_PATCH_response, "slug"),
        recipes_recipes_PATCH_1_request_body,
        recipe_name,
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_1_response, "slug") == recipes
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_1_response, "id"
    ) == skyramp.get_response_value(recipes_recipes_PATCH_response, "id")
    assert skyramp.check_schema(
        recipes_recipes_PATCH_1_response,
        r'{"prepTime": null, "cookTime": null, "performTime": null, "totalTime": null}',
    )
    # the counter must fall from 4 to 0 — it is recomputed on read, never cached at create time
    assert skyramp.get_response_value(recipes_recipes_PATCH_1_response, "timeFieldsCount") == 0
    assert skyramp.get_response_value(
        recipes_recipes_PATCH_1_response, "timeFieldsCount"
    ) < skyramp.get_response_value(recipes_recipes_PATCH_response, "timeFieldsCount")


if __name__ == "__main__":
    test_integration()
